mapper.select:
SELECT m.*, r.status AS run_status
FROM agent_message m INNER JOIN agent_run r ON r.id = m.run_id
WHERE m.session_id = #{sessionId}
ORDER BY m.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT m.*
FROM agent_message m
         INNER JOIN agent_run r ON r.id = m.run_id
WHERE m.session_id = #{sessionId}
  AND m.role = 'ASSISTANT'
  AND r.status = 'SUCCEEDED'
  AND m.id < #{beforeId}
ORDER BY m.id DESC
LIMIT #{limit}
